    (rho(t)::Real), [description = "Air density", output = true]
    (v_wind_x(t)::Real), [description = "Wind velocity, world frame, x component (world x is forward)", output = true]
    (v_wind_y(t)::Real), [description = "Wind velocity, world frame, y component (world y is up)", output = true]
    (v_wind_z(t)::Real), [description = "Wind velocity, world frame, z component (world z is to the right)", output = true]
  end
